package oracle;
import java.io.*;import java.util.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;
import core.game.node.Node;import core.game.node.entity.player.Player;import core.game.node.entity.npc.NPC;
import core.game.world.repository.*;import core.game.world.update.UpdateSequence;import core.net.packet.PacketProcessor;import core.net.packet.in.Packet;import core.integrations.grafana.Grafana;
public class Support {
 static Map input;static List<Object>events;static Map<String,Integer>calls;static Map<Integer,Node>nodes;static Map<String,List>lists;static UpdateSequence sequence;static int clockIndex;static boolean recording;public static int ticks;
 public static class Failure extends RuntimeException{String phase;Failure(String p){phase=p;}@Override public void printStackTrace(PrintWriter w){w.print("failure:"+phase+"\n");}@Override public void printStackTrace(){emit("exception",phase);}}
 public static class Phase{String name;public Phase(String n){name=n;}public void update(){emit(name);}public void updateAll(){emit(name);}public void tick(){emit(name);}}
 public static class Work extends Packet{Work(int id,boolean f){super(id,f);}}
 static int n(Object o){return((Number)o).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}
 static Node node(Object o){return o==null?null:nodes.get(n(o));}static Object id(Node n){return n==null?null:n.id;}
 public static void emit(String phase,Object...args){if(!recording)return;List<Object>row=new ArrayList<>();row.add(phase);row.addAll(Arrays.asList(args));events.add(row);int count=calls.merge(phase,1,Integer::sum);for(Object h:(List)input.getOrDefault("hooks",Collections.emptyList())){Map hook=(Map)h;if(phase.equals(hook.get("event"))&&count==v(hook,"at",1))for(Object a:(List)hook.get("actions"))act((Map)a);}if(count==v((Map)input.getOrDefault("failures",Collections.emptyMap()),phase,-1))throw new Failure(phase);}
 public static long clock(){List a=(List)input.getOrDefault("clock",Collections.emptyList());long value=clockIndex<a.size()?((Number)a.get(clockIndex)).longValue():clockIndex;clockIndex++;emit("clock",value);return value;}
 public static void process(Packet p){emit("packet",p.id);if(p.fail)throw new Failure(Integer.toString(p.id));}
 static Object act(Map a){String op=(String)a.get("op");List l=a.get("list")==null?null:lists.get(a.get("list"));Node node=node(a.get("node"));switch(op){
 case"add":return l.add(node);case"remove":return l.remove(node);case"insert":l.add(v(a,"index",0),node);return null;case"set":return id((Node)l.set(v(a,"index",0),node));case"removeAt":return id((Node)l.remove(v(a,"index",0)));case"clear":l.clear();return null;
 case"sync":UpdateSequence.getRenderablePlayers().sync();return null;case"start":sequence.start();return null;case"run":sequence.run();return null;case"end":sequence.end();return null;case"terminate":sequence.terminate();return null;
 case"handle":new core.worker.MajorUpdateWorker(sequence).handleTickActions(Boolean.TRUE.equals(a.get("skip")));return null;
 case"repo":if("npcs".equals(a.get("kind")))Repository.renderableNpcs=l;else Repository.lobbyPlayers=l;return null;
 case"captured":if("npcs".equals(a.get("kind")))sequence.setNpcList(l);else if("players".equals(a.get("kind")))sequence.setPlayersList(l);else sequence.setLobbyList(l);return null;
 case"enqueue":PacketProcessor.enqueue(new Work(v(a,"id",0),Boolean.TRUE.equals(a.get("fail"))));return null;case"no":PacketProcessor.enqueue(new Packet.NoProcess());return null;case"process":PacketProcessor.processQueue();return null;default:throw new IllegalArgumentException(op);}}
 static List ids(List list){List<Object>out=new ArrayList<>();for(Object n:list)out.add(id((Node)n));return out;}
 static String alias(List list){if(list==null)return null;for(Map.Entry<String,List> e:lists.entrySet())if(e.getValue()==list)return e.getKey();throw new IllegalArgumentException("unknown list");}
 static Queue pending()throws Exception{java.lang.reflect.Field f=InitializingNodeList.class.getDeclaredField("queue");f.setAccessible(true);return(Queue)f.get(UpdateSequence.getRenderablePlayers());}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);events=new ArrayList<>();calls=new HashMap<>();nodes=new TreeMap<>();for(int i=0;i<10;i++)nodes.put(i,i==3||i==4||i==7?new NPC(i):new Player(i));
 InitializingNodeList<Player>p=UpdateSequence.getRenderablePlayers();p.clear();pending().clear();lists=new TreeMap<>();lists.put("players",p);lists.put("npcs",new java.util.concurrent.CopyOnWriteArrayList());lists.put("lobby",new ArrayList());lists.put("other",new ArrayList());
 for(String name:Arrays.asList("players","npcs","lobby","other")){List initial=(List)input.getOrDefault(name,name.equals("players")?Arrays.asList(1L,2L):name.equals("npcs")?Arrays.asList(3L,4L):name.equals("lobby")?Arrays.asList(5L):Collections.emptyList());for(Object o:initial){Node value=node(o);if(name.equals("players"))p.add(p.size(),(Player)value);else lists.get(name).add(value);}}
 Repository.lobbyPlayers=lists.get("lobby");Repository.renderableNpcs=lists.get("npcs");sequence=new UpdateSequence();clockIndex=0;ticks=v(input,"ticks",0);recording=false;Grafana.INSTANCE.setPacketProcessTime(0);Grafana.INSTANCE.setNpcTickTime(0);Grafana.INSTANCE.setPlayerTickTime(0);Grafana.INSTANCE.setPlayerRenderTime(0);events.clear();calls.clear();PacketProcessor.reset();recording=true;List<Object>states=new ArrayList<>();
 for(Object a:(List)input.get("actions")){events.clear();Object result=null;String error=null;try{result=act((Map)a);}catch(Exception e){error=e instanceof Failure?((Failure)e).phase:e instanceof NullPointerException?"Null":e instanceof ConcurrentModificationException?"ConcurrentModification":e instanceof ClassCastException?"Type":e instanceof IndexOutOfBoundsException?"Index":e.getClass().getSimpleName();}
 Map<String,Object>s=new TreeMap<>();Map<String,Object>ls=new TreeMap<>();for(Map.Entry<String,List>e:lists.entrySet())ls.put(e.getKey(),ids(e.getValue()));s.put("lists",ls);List<Object>q=new ArrayList<>();for(Object e:pending()){InitializationEntry ie=(InitializationEntry)e;q.add(Arrays.asList(id(ie.getNode()),ie.isRemoval()));}s.put("pending",q);List<Object>ns=new ArrayList<>();for(Node n:nodes.values())ns.add(Arrays.asList(n.id,n.active,n.renderable));s.put("nodes",ns);s.put("captured",Arrays.asList(alias(sequence.getLobbyList()),alias(sequence.getPlayersList()),alias(sequence.getNpcList())));s.put("metrics",Arrays.asList(Grafana.INSTANCE.getNpcTickTime(),Grafana.INSTANCE.getPlayerTickTime(),Grafana.INSTANCE.getPlayerRenderTime()));s.put("clockIndex",clockIndex);s.put("ticks",ticks);s.put("packetTime",Grafana.INSTANCE.getPacketProcessTime());s.put("queue",PacketProcessor.snapshot());s.put("events",new ArrayList<>(events));s.put("result",result);s.put("error",error);states.add(s);}
 input.put("expected",states);System.out.println(JSONValue.toJSONString(input));}}}
}
